  for(const b of shooterState.bullets){for(const e of shooterState.enemies){if(e.hp>0&&Math.abs(b.x-e.x)<e.w*.52&&Math.abs(b.y-e.y)<e.h*.55){b.y=-50;e.hp--;if(e.hp<=0)shooterState.score+=e.boss?500: e.kind==='zig'?35:20;break;}}}
