  ctx.fillStyle='#060d25';ctx.fillRect(0,0,w,h);ctx.fillStyle='#b7d7ff';for(const st of shooterState.stars){ctx.globalAlpha=.35+st.s*.25;ctx.fillRect(st.x,st.y,st.s,st.s*1.8);}ctx.globalAlpha=1;
