  ctx.save();ctx.translate(p.x,p.y);if(now<p.invulnerableUntil&&Math.floor(now/100)%2===0)ctx.globalAlpha=.4;ctx.fillStyle='#51e2ff';ctx.beginPath();ctx.moveTo(0,-19);ctx.lineTo(15,13);ctx.lineTo(5,9);ctx.lineTo(0,15);ctx.lineTo(-5,9);ctx.lineTo(-15,13);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(-3,0,6,8);ctx.fillStyle='#ffb64d';ctx.beginPath();ctx.moveTo(-5,12);ctx.lineTo(0,24+Math.random()*5);ctx.lineTo(5,12);ctx.fill();ctx.restore();ctx.globalAlpha=1;
  for(const b of shooterState.bullets){ctx.fillStyle='#91fff0';ctx.shadowColor='#91fff0';ctx.shadowBlur=8;ctx.fillRect(b.x-2,b.y-8,4,12);}ctx.shadowBlur=0;
