 if(shouldAnimate)bearLastAnimatedShotId=latestShot.id;
 const animStart=shouldAnimate?performance.now():0;
 let aimAngle=45;
 const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
 function originX(){return side===0?94:806;}
 function lineEnd(a){const dir=side===0?1:-1,len=190;return {x:originX()+dir*Math.cos(a*Math.PI/180)*len,y:startY-Math.sin(a*Math.PI/180)*len};}
 function updatePower(now){const cycle=((now-chargeStart)%1800)/1800;const triangle=cycle<.5?cycle*2:(1-cycle)*2;power=20+triangle*80;bearChargePower=Math.round(power);const pl=document.getElementById('bearPowerLabel'),pf=document.getElementById('bearPowerFill');if(pl)pl.textContent=Math.round(power)+'%';if(pf)pf.style.width=power+'%';}
 function paint(t){
  ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#dff5ff');sky.addColorStop(1,'#fff0cf');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.fillStyle='#d6b66e';ctx.fillRect(0,ground,W,H-ground);
  ctx.fillStyle='#b99a56';for(let i=0;i<15;i++){const x=(i*61+23)%W,y=ground+10+(i*17)%48;ctx.fillRect(x,y,3,2);}
  if(dalgu.complete&&dalgu.naturalWidth)ctx.drawImage(dalgu,8,ground-112,84,108);else{ctx.font='48px sans-serif';ctx.fillText('🧸',14,ground-12)}
  if(salgu.complete&&salgu.naturalWidth)ctx.drawImage(salgu,W-92,ground-112,84,108);else{ctx.font='48px sans-serif';ctx.fillText('🧸',W-74,ground-12)}
  if(turn){const end=lineEnd(aimAngle);ctx.save();ctx.strokeStyle='#9c54d8';ctx.lineWidth=2.5;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(originX(),startY);ctx.lineTo(end.x,end.y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#9c54d8';ctx.beginPath();ctx.arc(end.x,end.y,4,0,Math.PI*2);ctx.fill();ctx.restore();}
  if(charging)updatePower(t);
  let keepAnimating=false;
  if(trajectory.length&&animStart){const duration=850,progress=clamp((t-animStart)/duration,0,1),path=trajectory;const f=progress*(path.length-1),idx=Math.floor(f),mix=f-idx,a=path[idx],b=path[Math.min(path.length-1,idx+1)],x=(a.x+(b.x-a.x)*mix)*W,y=(a.y+(b.y-a.y)*mix)*H;ctx.save();ctx.translate(x,y);ctx.rotate(shotDir*(progress*5));ctx.font='30px system-ui, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor='#5a4c6a55';ctx.shadowBlur=4;ctx.fillText(latestShot.icon||(shotSide===0?'☎️':'🎧'),0,0);ctx.restore();if(progress>=1){ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillStyle=latestShot.hit?'#d92955':'#5e5874';ctx.fillText(latestShot.hit?'💥 명중!':'💨 빗나감!',x,Math.max(32,y-20));}else keepAnimating=true;}
  if(charging||turn||keepAnimating)bearCanvasRaf=requestAnimationFrame(paint);else bearCanvasRaf=0;
 }
 canvas.onpointermove=e=>{if(!turn||charging)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;const dx=(x-originX())*(side===0?1:-1),dy=startY-y;const raw=Math.atan2(dy,Math.max(1,dx))*180/Math.PI;aimAngle=clamp(raw,20,80);bearAimAngle=aimAngle;const lab=document.getElementById('bearAngleLabel');if(lab)lab.textContent=Math.round(aimAngle)+'°';};
 canvas.onpointerdown=e=>{if(!turn||charging)return;e.preventDefault();try{canvas.setPointerCapture(e.pointerId)}catch(_){}charging=true;chargeStart=performance.now();bearCharging=true;updatePower(chargeStart);if(!bearCanvasRaf)bearCanvasRaf=requestAnimationFrame(paint);};
