 canvas.onpointercancel=()=>{charging=false;bearCharging=false;};canvas.onlostpointercapture=()=>{if(charging){charging=false;bearCharging=false;}};canvas.style.cursor=turn?'crosshair':'default';
 // Keep a single animation loop per canvas; never start overlapping RAF loops.
